'use strict';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();const clone=x=>JSON.parse(JSON.stringify(x));
function fresh(){return {rateCatalogVersion:2,selected:null,rates:[],docs:[],trips:[]}}
let state=fresh();
state.rateCatalogVersion=2;state.supplierSafetyVersion=1;
state.trips.forEach(t=>t.quote?.forEach(q=>{if(q.supplierOfferSnapshot?.offerId&&!q.supplierOfferSnapshot.rateId)q.supplierOfferSnapshot.rateId=q.id}));
state.quoteCalculationVersion=1;
let day=1,busy=false,lastFocus,timer,searchTimer;
function save(){return false}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function trip(){return state.trips.find(t=>t.id===state.selected)||state.trips[0]}
function total(t=trip()){return t.quote.reduce((s,r)=>s+r.qty*r.price,0)}
function status(s){return {NEW:'Chưa tạo hành trình',DRAFT:'Đang soạn',REVIEWED:'Đã rà soát'}[s]||s}
function badge(s){return '<span class="badge '+(s==='REVIEWED'?'green':s==='NEW'?'gray':'amber')+'">'+status(s)+'</span>'}
function route(){const [name,q]=(location.hash.slice(1)||'trips').split('?');return {name,p:new URLSearchParams(q||'')}}
function mins(s){const [h,m]=s.split(':').map(Number);return h*60+m}
function hm(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function date(s){return new Date(s+'T12:00:00').toLocaleDateString('vi-VN')}
function dayDate(t,d){const x=new Date(t.date+'T12:00:00');x.setDate(x.getDate()+d-1);return x.toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit'})}
function checks(t=trip()){const out=[];if(!t.activities.length)out.push({level:'error',title:'Chưa có lịch trình',detail:'Tạo lịch trình bằng trợ lý hoặc thêm hoạt động.'});if(!t.quote.length)out.push({level:'error',title:'Chưa có báo giá',detail:'Tạo lịch trình bằng trợ lý để xem chi phí.'});if(total(t)>t.budget)out.push({level:'error',title:'Tổng chi phí vượt ngân sách',detail:'Vượt '+money(total(t)-t.budget)+'. Điều chỉnh báo giá hoặc ngân sách.'});for(let d=1;d<=t.days;d++){const acts=t.activities.filter(a=>a.day===d).sort((a,b)=>a.start.localeCompare(b.start));acts.forEach((a,i)=>{if(mins(a.end)<=mins(a.start))out.push({level:'error',title:'Thời gian chưa hợp lệ',detail:a.title});if(i&&mins(a.start)<mins(acts[i-1].end)+(acts[i-1].travel||0))out.push({level:'error',title:'Chưa đủ thời gian di chuyển',detail:'Ngày '+d+': '+acts[i-1].title+' và '+a.title,fix:a.id})});if(t.activities.length&&!acts.length)out.push({level:'warn',title:'Ngày '+d+' chưa có hoạt động',detail:'Thêm hoạt động hoặc xác nhận thời gian tự do.'})}out.push({level:'warn',title:'Thông tin dịch vụ cần xác minh',detail:'Giờ hoạt động, đơn giá và thời tiết chưa kết nối nguồn thực tế.'});return out}
function mutate(t,s){t.revision++;t.status='DRAFT';save();render();if(s)toast(s)}
function openModal(title,body){lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;modal.showModal();setTimeout(()=>modal.querySelector('input,textarea,select,button')?.focus(),0)}
function closeModal(){modal.close();if(lastFocus?.isConnected)lastFocus.focus()}
$('#close-modal').onclick=closeModal;modal.addEventListener('cancel',()=>setTimeout(()=>lastFocus?.isConnected&&lastFocus.focus(),0));
const btn=(s,a,c='')=>'<button class="btn '+c+'" data-action="'+a+'">'+s+'</button>';
const heading=(eye,title,desc,actions='')=>'<div class="heading"><div><div class="eyebrow">'+eye+'</div><h1>'+title+'</h1><p>'+desc+'</p></div><div class="actions">'+actions+'</div></div>';
function search(id,ph,v=''){return '<div class="search"><span>⌕</span><input id="'+id+'" aria-label="'+ph+'" placeholder="'+ph+'" value="'+esc(v)+'"><button data-clear="'+id+'" aria-label="Xóa tìm kiếm" '+(!v?'hidden':'')+'>×</button></div>'}
function render(){if(route().name==='workspace'&&!trip()){app.innerHTML='<section class="panel empty"><h2>Chưa chọn chuyến đi</h2><p>Tạo chuyến đi mới hoặc chọn một chuyến từ danh sách.</p><a class="btn primary" href="#intake">Tạo chuyến đi</a></section>';return}const r=route(),names={trips:'Chuyến đi',workspace:'Không gian tư vấn',knowledge:'Kho tri thức',rates:'Bảng giá dịch vụ',settings:'Cài đặt & dữ liệu'};document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===r.name);a.dataset.nav===r.name?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});$('#route-label').textContent=names[r.name]||'Không tìm thấy';document.title='Tripwise — '+(names[r.name]||'Không tìm thấy');({trips:renderTrips,workspace:renderWorkspace,knowledge:renderKnowledge,rates:renderRates,settings:renderSettings}[r.name]||(()=>app.innerHTML='<div class="panel empty"><h3>Không tìm thấy trang</h3><a href="#trips" class="btn">Về Chuyến đi</a></div>'))()}
function renderTrips(){const q=route().p.get('q')||'',f=route().p.get('status')||'',items=state.trips.filter(t=>(t.name+' '+t.client).toLowerCase().includes(q.toLowerCase())&&(!f||f===t.status));app.innerHTML=heading('HÀNH TRÌNH BẮT ĐẦU TỪ ĐÂY','Chào Khôi, cùng tạo chuyến đi mới.','Quản lý yêu cầu và biến ý tưởng của khách thành hành trình phù hợp.',btn('＋ Tạo chuyến đi','new-trip','primary'))+'<section class="hero"><div class="hero-copy"><div class="eyebrow">TRIPWISE ASSISTANT</div><h2>Mỗi chuyến đi,<br>một câu chuyện riêng.</h2><p>Kết hợp nhu cầu khách hàng, kinh nghiệm nội bộ và ngân sách trong cùng một không gian tư vấn.</p>'+''+'</div><div class="hero-photo"><img src="assets/seoul.jpg" alt="Cung điện và cảnh quan Seoul"><span>Seoul, Hàn Quốc</span></div></section><div class="stats">'+[['Tổng chuyến đi',state.trips.length,'Trong không gian của bạn'],['Đang xây dựng',state.trips.filter(t=>t.status!=='REVIEWED').length,'Yêu cầu cần tiếp tục tư vấn'],['Đã rà soát',state.trips.filter(t=>t.status==='REVIEWED').length,'Phương án đã kiểm tra nội bộ']].map(x=>'<div class="stat"><div class="stat-label">'+x[0]+'<span>✧</span></div><b>'+x[1]+'</b><small>'+x[2]+'</small></div>').join('')+'</div><section class="panel pad"><div class="section-head"><div><h2>Chuyến đi của bạn</h2><p>Tiếp tục từ phương án gần nhất.</p></div></div><div class="toolbar">'+search('trip-search','Tìm chuyến đi, khách hàng...',q)+'<select class="filter" id="status-filter" aria-label="Lọc trạng thái"><option value="">Tất cả trạng thái</option><option value="NEW">Chưa tạo hành trình</option><option value="DRAFT">Đang soạn</option><option value="REVIEWED">Đã rà soát</option></select><span class="count">'+items.length+' chuyến đi</span></div><div class="table-wrap"><table><thead><tr><th>CHUYẾN ĐI / KHÁCH HÀNG</th><th>KHỞI HÀNH</th><th>NHÓM KHÁCH</th><th>NGÂN SÁCH</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>'+items.map(t=>'<tr><td><div class="name-cell"><span class="initial">♧</span><button class="table-link" data-open="'+t.id+'"><strong>'+esc(t.name)+'</strong><small>'+esc(t.client)+'</small></button></div></td><td>'+date(t.date)+'<small>'+t.days+' ngày</small></td><td>'+(t.adults+t.children)+' khách<small>'+t.adults+' người lớn, '+t.children+' trẻ em</small></td><td>'+money(t.budget)+'</td><td>'+badge(t.status)+'</td><td><button class="icon-btn" data-open="'+t.id+'" aria-label="Mở '+esc(t.name)+'">↗</button></td></tr>').join('')+'</tbody></table></div>'+(!items.length?'<div class="empty"><h3>Không tìm thấy chuyến đi</h3><p>Thử từ khóa khác hoặc bỏ bộ lọc.</p></div>':'')+'<div class="table-foot"><span>Hiển thị '+items.length+' / '+state.trips.length+' chuyến đi</span></div></section>';$('#status-filter').value=f}


function renderWorkspace(){const t=trip(),tab=route().p.get('tab')||'itinerary';day=Math.max(1,Math.min(day,t.days));const errors=checks(t).filter(x=>x.level==='error'),cats={};t.quote.forEach(r=>cats[r.category]=(cats[r.category]||0)+r.qty*r.price);
const left='<aside class="panel requirements"><h2>Yêu cầu chuyến đi</h2><div class="client"><span class="avatar">M</span><div><b>'+esc(t.client)+'</b><small>Yêu cầu tư vấn cá nhân</small></div></div><div class="info-grid">'+[['ĐIỂM ĐẾN',t.destination],['THỜI GIAN',t.days+' ngày'],['KHỞI HÀNH',date(t.date)],['NHÓM KHÁCH',(t.adults+t.children)+' khách']].map(x=>'<div><span class="label">'+x[0]+'</span><span class="value">'+esc(x[1])+'</span></div>').join('')+'</div><span class="label">SỞ THÍCH & YÊU CẦU</span><div class="tags">'+t.tags.map(x=>'<span class="tag">'+esc(x)+'</span>').join('')+'</div><div class="request-text">'+esc(t.request)+'</div>'+btn('Chỉnh sửa yêu cầu','edit-trip','full')+'<div class="chat"><h3>✧ &nbsp; Trợ lý hành trình</h3><div class="bubble">'+esc(t.chat||'Tạo lịch trình bằng trợ lý để bắt đầu khám phá hành trình.')+'</div><form id="chat-form" novalidate><label class="label" for="chat-input">Điều chỉnh yêu cầu</label><textarea id="chat-input" placeholder="Ví dụ: giảm ngân sách còn 100 triệu"></textarea><button type="submit" aria-label="Gửi yêu cầu">↑</button></form><p class="hint">Yêu cầu được gửi đến trợ lý Tripwise.</p></div></aside>';
const center='<div class="work-main"><div class="tabs" aria-label="Nội dung chuyến đi">'+[['itinerary','Hành trình'],['quote','Báo giá'],['checks','Kiểm tra'+(errors.length?' ('+errors.length+')':'')],['versions','Phiên bản']].map(([k,v])=>'<a href="#workspace?tab='+k+'" class="'+(tab===k?'active':'')+'" '+(tab===k?'aria-current="page"':'')+'>'+v+'</a>').join('')+'</div>'+workspaceContent(t,tab)+'</div>';
const right='<aside class="summary"><section class="panel budget"><div class="budget-title">Chi phí dự kiến</div><div class="amount">'+(total(t)/1000000).toLocaleString('vi-VN',{maximumFractionDigits:1})+' <small>triệu đồng</small></div><span class="badge '+(total(t)>t.budget?'red':'green')+'">'+(total(t)>t.budget?'Vượt ngân sách':'Trong ngân sách')+'</span><div class="bar"><div style="width:'+Math.min(100,total(t)/t.budget*100)+'%;'+(total(t)>t.budget?'background:#b05d43':'')+'"></div></div><div class="bar-caption"><span>'+Math.round(total(t)/t.budget*100)+'% ngân sách</span><span>'+money(t.budget)+'</span></div><div class="budget-details">'+Object.entries(cats).map(([k,v])=>'<div class="money-row"><span>'+esc(k)+'</span><b>'+money(v)+'</b></div>').join('')+'<div class="money-row total"><span>'+(total(t)>t.budget?'Vượt':'Còn lại')+'</span><b>'+money(Math.abs(t.budget-total(t)))+'</b></div></div></section><section class="panel check"><h3>Kiểm tra phương án</h3><div class="check-row"><i>'+(errors.length?'!':'✓')+'</i><span>'+errors.length+' vấn đề cần xử lý</span></div><div class="check-row"><i>✓</i><span>'+t.activities.length+' hoạt động trong lịch trình</span></div><div class="check-row"><i>◷</i><span>Thông tin dịch vụ cần xác minh</span></div><a href="#workspace?tab=checks" class="btn full">Xem kiểm tra</a></section><section class="suggestion"><h3>✧ &nbsp; Một gợi ý cho gia đình</h3><p>Giữ khoảng nghỉ giữa các điểm để trẻ nhỏ có thời gian nghỉ ngơi.</p>'+btn('Áp dụng nhịp độ thoải mái','relax')+'</section><div class="version-note">Bản chỉnh sửa '+t.revision+' · '+status(t.status)+'</div></aside>';
app.innerHTML=heading('KHÔNG GIAN TƯ VẤN',esc(t.name),'<a href="#trips">Chuyến đi</a> &nbsp; / &nbsp; '+esc(t.client)+' &nbsp; '+badge(t.status),btn('↗ Xuất phương án','export')+btn('Lưu phiên bản','snapshot')+'<button class="btn primary" data-action="generate" '+(busy?'disabled':'')+'>'+(busy?'Đang tạo lịch trình…':'✧ Tạo lịch trình bằng trợ lý')+'</button>')+'<div class="workspace">'+left+center+right+'</div>'}
function workspaceContent(t,tab){if(tab==='itinerary'){const acts=t.activities.filter(a=>a.day===day).sort((a,b)=>a.start.localeCompare(b.start));return '<div class="banner"><img src="assets/seoul.jpg" alt="Cảnh quan Seoul"><div><h2>'+esc(t.destination)+'</h2><p>'+t.days+' ngày · '+(t.adults+t.children)+' khách · Lịch trình đang soạn</p></div></div><section class="panel itinerary"><div class="section-head"><div><h2>Hành trình của bạn</h2><p>Linh hoạt chỉnh sửa theo nhu cầu khách hàng.</p></div><span class="badge">'+t.activities.length+' hoạt động</span></div><div class="day-nav">'+Array.from({length:t.days},(_,i)=>'<button data-day="'+(i+1)+'" class="'+(day===i+1?'active':'')+'" aria-pressed="'+(day===i+1)+'">Ngày '+(i+1)+'</button>').join('')+'</div><div class="day-head"><h3>Ngày '+day+' · '+dayDate(t,day)+'</h3><small>'+acts.length+' hoạt động</small></div>'+acts.map(a=>'<article class="activity"><div class="time">'+a.start+'</div><div class="activity-card '+(a.locked?'locked':'')+'"><div class="activity-top"><span class="emoji">'+a.icon+'</span><div><h4>'+esc(a.title)+'</h4><p>'+esc(a.description)+'</p></div><div class="activity-actions"><button class="icon-btn" data-lock="'+a.id+'" aria-label="'+(a.locked?'Bỏ khóa':'Khóa')+' hoạt động" title="'+(a.locked?'Đã khóa':'Khóa hoạt động')+'">'+(a.locked?'▣':'□')+'</button><button class="icon-btn" data-edit-activity="'+a.id+'" aria-label="Sửa '+esc(a.title)+'" '+(a.locked?'disabled':'')+'>✎</button></div></div><div class="meta"><span>◷ '+a.start+' – '+a.end+'</span><span>⌖ '+esc(a.location)+'</span>'+(a.locked?'<span class="price">Đã khóa</span>':'')+'</div></div></article>').join('')+(!acts.length?'<div class="empty"><h3>Chưa có hoạt động</h3><p>Tạo lịch trình bằng trợ lý hoặc thêm hoạt động vào ngày này.</p></div>':'')+'<button class="add" data-action="add-activity">＋ Thêm hoạt động</button></section>'}
if(tab==='quote')return '<section class="panel quote"><div class="section-head"><div><h2>Báo giá dịch vụ</h2><p>Đơn giá theo nguồn báo giá của chuyến đi.</p></div><span class="badge">Có thể chỉnh sửa</span></div><div class="table-wrap"><table><thead><tr><th>DỊCH VỤ</th><th>SL</th><th>ĐƠN GIÁ</th><th>THÀNH TIỀN</th></tr></thead><tbody>'+t.quote.map(r=>'<tr><td><b>'+esc(r.name)+'</b><small>'+esc(r.unit)+'</small></td><td><input type="number" min="0" max="9999" step="1" value="'+r.qty+'" data-quote="'+r.id+'" data-field="qty" aria-label="Số lượng '+esc(r.name)+'"></td><td><input type="number" min="0" max="1000000000" step="1000" class="price-input" value="'+r.price+'" data-quote="'+r.id+'" data-field="price" aria-label="Đơn giá '+esc(r.name)+'"></td><td>'+money(r.qty*r.price)+'</td></tr>').join('')+'</tbody></table></div>'+(!t.quote.length?'<div class="empty">Chưa có báo giá. Hãy tạo lịch trình bằng trợ lý.</div>':'')+'<div class="quote-total"><span>Tổng chi phí dự kiến</span><b>'+money(total(t))+'</b></div><p class="hint">Thay đổi số lượng hoặc đơn giá để xem tổng tiền cập nhật.</p></section>';
if(tab==='checks'){const list=checks(t);return '<section class="panel pad"><div class="section-head"><div><h2>Kiểm tra tính khả thi</h2><p>Thời gian, di chuyển và ngân sách.</p></div>'+btn('Kiểm tra lại','recheck')+'</div>'+list.map(c=>'<div class="validation '+c.level+'"><span class="symbol">'+(c.level==='error'?'!':'◷')+'</span><div><h3>'+esc(c.title)+'</h3><p>'+esc(c.detail)+'</p></div>'+(c.fix?'<button class="btn" data-fix="'+c.fix+'">Sửa giờ</button>':'')+'</div>').join('')+(!list.some(x=>x.level==='error')?'<div class="validation"><span class="symbol">✓</span><div><h3>Đạt kiểm tra thời gian và ngân sách</h3><p>Nhân viên cần tiếp tục xác minh thông tin dịch vụ.</p></div></div>':'')+'<div class="form-actions">'+''+'</div></section>'}
if(tab==='versions')return '<section class="panel pad"><div class="section-head"><div><h2>Phiên bản phương án</h2><p>Lưu hành trình và báo giá cùng nhau.</p></div>'+btn('＋ Lưu phiên bản','snapshot','primary')+'</div>'+(!t.versions.length?'<div class="empty"><h3>Chưa có phiên bản đã lưu</h3><p>Lưu một bản để khôi phục sau khi chỉnh sửa.</p></div>':t.versions.slice().reverse().map(v=>'<div class="version-item"><div><h3>'+esc(v.name)+'</h3><p>'+new Date(v.at).toLocaleString('vi-VN')+' · '+v.activities.length+' hoạt động · '+money(v.quote.reduce((s,r)=>s+r.qty*r.price,0))+'</p></div><button class="btn" data-restore="'+v.id+'">Khôi phục</button></div>').join(''))+'</section>';return '<div class="panel empty">Không tìm thấy nội dung. <a href="#workspace">Xem hành trình</a></div>'}
function renderKnowledge(){const q=route().p.get('q')||'',items=state.docs.filter(d=>(d.title+' '+d.description).toLowerCase().includes(q.toLowerCase()));app.innerHTML=heading('KINH NGHIỆM ĐƯỢC KẾT NỐI','Kho tri thức nội bộ','Lưu cẩm nang, quy trình và kinh nghiệm để đội ngũ dùng lại khi tư vấn.',btn('＋ Thêm tài liệu','new-doc','primary'))+'<div class="toolbar">'+search('doc-search','Tìm trong kho tri thức...',q)+'<span class="count">'+items.length+' tài liệu</span></div><div class="knowledge-grid">'+items.map(d=>'<article class="panel doc-card"><span class="doc-icon">▤</span><h3><button type="button" class="doc-title" data-doc="'+d.id+'">'+esc(d.title)+'</button></h3><p>'+esc(d.description||'')+'</p></article>').join('')+'</div>'+(!items.length?'<div class="panel empty"><h3>Chưa có kết quả</h3><p>Thử từ khóa khác hoặc thêm tài liệu mới.</p></div>':'')}
function renderRates(){const q=route().p.get('q')||'',items=state.rates.filter(r=>(r.name+' '+r.category).toLowerCase().includes(q.toLowerCase()));app.innerHTML=heading('DỮ LIỆU DỊCH VỤ','Bảng giá dịch vụ','Quản lý đơn giá làm cơ sở xây dựng phương án.',btn('＋ Thêm dịch vụ','new-rate','primary'))+'<div class="subtle">Dịch vụ và giá tham khảo dùng để lập báo giá trong Không gian tư vấn.</div><section class="panel pad"><div class="toolbar">'+search('rate-search','Tìm dịch vụ, nhóm dịch vụ...',q)+'<span class="count">'+items.length+' dịch vụ</span></div><div class="table-wrap"><table><thead><tr><th>DỊCH VỤ</th><th>NHÓM</th><th>ĐƠN VỊ</th><th>ĐƠN GIÁ</th><th>NGUỒN</th><th></th></tr></thead><tbody>'+items.map(r=>'<tr><td><strong>'+esc(r.name)+'</strong></td><td><span class="badge">'+esc(r.category)+'</span></td><td>'+esc(r.unit)+'</td><td>'+money(r.price)+'</td><td>Danh mục nhà cung cấp</td><td><button class="icon-btn" data-edit-rate="'+r.id+'" aria-label="Sửa '+esc(r.name)+'">✎</button></td></tr>').join('')+'</tbody></table></div>'+(!items.length?'<div class="empty">Không có dịch vụ phù hợp.</div>':'')+'<div class="form-actions">'+''+'</div></section>'}
function renderSettings(){app.innerHTML=heading('DỮ LIỆU CỦA BẠN','Cài đặt & dữ liệu','Tải bản sao các chuyến đi và tài liệu của bạn.')+'<div class="settings-grid settings-export"><section class="panel pad"><h2>Sao lưu dữ liệu</h2><p>Tải xuống bản sao gồm chuyến đi, lịch trình, báo giá và tài liệu trong Tripwise.</p><div class="actions">'+btn('↓ Tải bản sao','export-data')+'</div><p class="hint">Bạn có thể lưu tệp này để dùng làm bản dự phòng.</p></section></div>'}


function field(name,label,v='',type='text',wide=false){return '<div class="field '+(wide?'wide':'')+'"><label for="f-'+name+'">'+label+'</label><input id="f-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(v)+'"></div>'}
function form(body,submit='Lưu thay đổi'){return '<form id="edit-form" novalidate><div class="form-grid">'+body+'<div class="form-error" id="form-error" role="alert"></div></div><div class="form-actions"><button type="button" class="btn" data-action="cancel">Hủy</button><button type="submit" class="btn primary">'+submit+'</button></div></form>'}
function error(s){$('#form-error').textContent=s}
function tripForm(edit){const t=edit?trip():{name:'',client:'',destination:'Seoul, Hàn Quốc',date:'2027-04-05',days:5,adults:4,children:2,budget:120000000,request:''};openModal(edit?'Chỉnh sửa yêu cầu':'Tạo chuyến đi',form(field('name','Tên chuyến đi',t.name,'text',true)+field('client','Khách hàng',t.client)+field('destination','Điểm đến',t.destination)+field('date','Ngày khởi hành',t.date,'date')+field('days','Số ngày (1–14)',t.days,'number')+field('adults','Người lớn',t.adults,'number')+field('children','Trẻ em',t.children,'number')+field('budget','Ngân sách toàn đoàn (VND)',t.budget,'number',true)+'<div class="field wide"><label for="f-request">Yêu cầu & sở thích</label><textarea name="request" id="f-request">'+esc(t.request)+'</textarea></div>',edit?'Lưu yêu cầu':'Tạo chuyến đi'));$('#edit-form').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!x.name.trim()||!x.client.trim()||!x.destination.trim()||!x.date)return error('Nhập tên chuyến đi, khách hàng, điểm đến và ngày khởi hành.');for(const k of ['days','adults','children','budget'])x[k]=Number(x[k]);if(!Number.isInteger(x.days)||x.days<1||x.days>14||!Number.isInteger(x.adults)||x.adults<1||x.adults>100||!Number.isInteger(x.children)||x.children<0||x.children>20||!Number.isFinite(x.budget)||x.budget<=0)return error('Kiểm tra số ngày, số khách và ngân sách hợp lệ.');if(edit&&x.days<t.days&&t.activities.some(a=>a.day>x.days))return error('Chuyển hoặc xóa các hoạt động cuối chuyến trước khi giảm số ngày.');if(edit){Object.assign(t,x);closeModal();mutate(t,'Đã cập nhật yêu cầu và kiểm tra lại ngân sách.')}else{const n={...x,id:uid(),tags:['Theo yêu cầu'],activities:[],quote:[],versions:[],status:'NEW',revision:1,chat:''};state.trips.push(n);state.selected=n.id;save();closeModal();day=1;location.hash='workspace';render();toast('Đã tạo chuyến đi. Thêm hoạt động hoặc tạo lịch trình bằng trợ lý.')}}}
function activityForm(id){const t=trip(),a=id?t.activities.find(a=>a.id===id):{day,start:'09:00',end:'11:00',title:'',location:'',description:'',travel:20};if(a.locked)return toast('Bỏ khóa hoạt động trước khi chỉnh sửa.');openModal(id?'Chỉnh sửa hoạt động':'Thêm hoạt động',form(field('title','Tên hoạt động',a.title,'text',true)+field('day','Ngày trong hành trình',a.day,'number')+field('location','Địa điểm',a.location)+field('start','Bắt đầu',a.start,'time')+field('end','Kết thúc',a.end,'time')+field('travel','ai chuyển đến điểm kế tiếp (phút)',a.travel,'number',true)+'<div class="field wide"><label for="f-description">Mô tả</label><textarea name="description" id="f-description">'+esc(a.description)+'</textarea></div>')+(id?'<button class="btn danger" data-delete="'+id+'" style="margin-top:12px">Xóa hoạt động</button>':''));$('#edit-form').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.day=Number(x.day);x.travel=Number(x.travel);if(!x.title.trim()||!x.location.trim()||!x.start||!x.end||mins(x.end)<=mins(x.start)||!Number.isInteger(x.day)||x.day<1||x.day>t.days||!Number.isFinite(x.travel)||x.travel<0||x.travel>240)return error('Nhập tên, địa điểm, ngày hợp lệ và giờ kết thúc sau bắt đầu. ai chuyển từ 0–240 phút.');if(id)Object.assign(a,x);else t.activities.push({...x,id:uid(),icon:'♧',locked:false});day=x.day;closeModal();mutate(t,'Đã lưu hoạt động và kiểm tra lại thời gian.')}}
function snapshot(t=trip(),silent=false){t.versions.push({id:uid(),name:'Phiên bản '+(t.versions.length+1),at:new Date().toISOString(),activities:clone(t.activities),quote:clone(t.quote),requirements:Object.fromEntries(['name','client','destination','date','days','adults','children','budget','request','tags'].map(k=>[k,clone(t[k])]))});save();if(!silent){render();toast('Đã lưu yêu cầu, lịch trình và báo giá trong cùng phiên bản.')}}
function docForm(){openModal('Thêm tài liệu nội bộ',form(field('title','Tên tài liệu','','text',true)+field('type','Loại tài liệu','Kinh nghiệm')+field('description','Mô tả ngắn')+'<div class="field wide"><label for="f-body">Nội dung</label><textarea id="f-body" name="body"></textarea></div>','Thêm tài liệu'));$('#edit-form').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!x.title.trim()||!x.body.trim())return error('Nhập tên và nội dung tài liệu.');state.docs.push({...x,id:uid()});save();closeModal();render();toast('Đã thêm tài liệu vào kho tri thức.')}}
function rateForm(id){const r=id?state.rates.find(r=>r.id===id):{name:'',category:'Tham quan',unit:'người'};openModal(id?'Chỉnh sửa dịch vụ':'Thêm dịch vụ',form(field('name','Tên dịch vụ',r.name,'text',true)+field('category','Nhóm dịch vụ',r.category)+field('unit','Đơn vị',r.unit)));$('#edit-form').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));if(!x.name.trim()||!x.category.trim()||!x.unit.trim())return error('Nhập tên, nhóm và đơn vị dịch vụ.');if(id)Object.assign(r,x);else state.rates.push({...x,id:uid(),qty:1,offers:[]});save();closeModal();render();toast('Đã lưu dịch vụ. Thêm báo giá nhà cung cấp để sử dụng.')}}
function offerForm(rateId,offerId){const r=state.rates.find(r=>r.id===rateId);if(!r)return;const o=offerId?r.offers.find(o=>o.id===offerId):{provider:'',price:0,validUntil:'',terms:'',status:'UNVERIFIED'};openModal(offerId?'Chỉnh sửa báo giá':'Thêm báo giá nhà cung cấp',form('<div class="field wide"><span class="label">Dịch vụ</span><strong>'+esc(r.name)+'</strong></div>'+field('provider','Nhà cung cấp',o.provider,'text',true)+field('price','Đơn giá (VND)',o.price,'number')+field('validUntil','Hiệu lực đến',o.validUntil,'date')+'<div class="field"><label for="f-status">Trạng thái xác minh</label><select id="f-status" name="status"><option value="UNVERIFIED" '+(o.status==='UNVERIFIED'?'selected':'')+'>Chưa xác minh</option><option value="VERIFIED" '+(o.status==='VERIFIED'?'selected':'')+'>Đã xác minh</option></select></div><div class="field wide"><label for="f-terms">Điều kiện áp dụng</label><textarea id="f-terms" name="terms">'+esc(o.terms)+'</textarea></div>'));$('#edit-form').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.price=Number(x.price);if(!x.provider.trim()||!Number.isInteger(x.price)||x.price<0||x.price>1e9||!x.validUntil)return error('Nhập nhà cung cấp, giá VND nguyên từ 0 đến 1 tỷ và ngày hết hiệu lực.');if(offerId)Object.assign(o,x);else r.offers.push({...x,id:uid()});save();closeModal();render();toast('Đã lưu báo giá nhà cung cấp. Báo giá chuyến đi hiện tại không bị thay đổi.')}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function exportTrip(){const t=trip();const text='<!doctype html><html lang="vi"><meta charset="utf-8"><title>'+esc(t.name)+'</title><style>body{font:15px/1.7 Arial;max-width:900px;margin:40px auto;padding:20px;color:#23432e}h1,h2{color:#064d3b}table{width:100%;border-collapse:collapse}td,th{padding:10px;border:1px solid #dde5d5;text-align:left}@media print{body{margin:0}}</style><h1>'+esc(t.name)+'</h1><p>'+esc(t.client)+' · '+date(t.date)+' · '+t.days+' ngày · '+(t.adults+t.children)+' khách</p><p>BẢN MẪU MINH HỌA. Chưa xác nhận giá hoặc dịch vụ thực tế. Trạng thái: '+status(t.status)+'</p>'+Array.from({length:t.days},(_,i)=>'<h2>Ngày '+(i+1)+'</h2>'+t.activities.filter(a=>a.day===i+1).sort((a,b)=>a.start.localeCompare(b.start)).map(a=>'<p><b>'+a.start+' – '+a.end+' · '+esc(a.title)+'</b><br>'+esc(a.location)+'<br>'+esc(a.description)+'</p>').join('')).join('')+'<h2>Báo giá dự kiến</h2><table><tr><th>Dịch vụ</th><th>SL</th><th>Đơn giá</th><th>Thành tiền</th></tr>'+t.quote.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+r.qty+' '+esc(r.unit)+'</td><td>'+money(r.price)+'</td><td>'+money(r.qty*r.price)+'</td></tr>').join('')+'</table><h2>Tổng: '+money(total(t))+'</h2><p>Ngân sách: '+money(t.budget)+'</p>';download('Tripwise-phuong-an.html',text,'text/html;charset=utf-8');toast('Đã tải phương án HTML. Mở file và chọn In để lưu PDF.')}


function click(e){const b=e.target.closest('button,a');if(!b)return;const t=trip();if(b.dataset.open){state.selected=b.dataset.open;day=1;save();location.hash='workspace';render();return}
if(b.dataset.day){day=+b.dataset.day;render();return}
if(b.dataset.clear){const r=route();r.p.delete('q');location.hash=r.name+(r.p.size?'?'+r.p:'');render();return}
if(b.dataset.lock){const a=t.activities.find(a=>a.id===b.dataset.lock);a.locked=!a.locked;mutate(t,a.locked?'Đã khóa hoạt động.':'Đã bỏ khóa hoạt động.');return}
if(b.dataset.editActivity)return activityForm(b.dataset.editActivity);
if(b.dataset.delete){openModal('Xóa hoạt động','<p class="doc-body">Xóa hoạt động này khỏi hành trình hiện tại? Phiên bản đã lưu vẫn được giữ lại.</p><div class="form-actions">'+btn('Hủy','cancel')+'<button class="btn danger" data-confirm-delete="'+b.dataset.delete+'">Xóa hoạt động</button></div>');return}
if(b.dataset.confirmDelete){t.activities=t.activities.filter(a=>a.id!==b.dataset.confirmDelete);closeModal();mutate(t,'Đã xóa hoạt động.');return}
if(b.dataset.fix){const a=t.activities.find(a=>a.id===b.dataset.fix),acts=t.activities.filter(x=>x.day===a.day).sort((a,b)=>a.start.localeCompare(b.start)),prev=acts[acts.indexOf(a)-1];if(a.locked)return toast('Bỏ khóa hoạt động trước khi sửa giờ.');if(prev){const start=mins(prev.end)+(prev.travel||0),duration=mins(a.end)-mins(a.start);if(start+duration>=1440)return toast('Không đủ thời gian trong ngày. Chuyển hoạt động sang ngày khác.');a.start=hm(start);a.end=hm(start+duration);mutate(t,'Đã sửa giờ và kiểm tra lại lịch trình.')}return}
if(b.dataset.restore){const v=t.versions.find(v=>v.id===b.dataset.restore);openModal('Khôi phục phiên bản','<p class="doc-body">Khôi phục '+esc(v.name)+'? Hệ thống lưu bản hiện tại trước khi thay đổi.</p><div class="form-actions">'+btn('Hủy','cancel')+'<button class="btn primary" data-confirm-restore="'+v.id+'">Khôi phục</button></div>');return}
if(b.dataset.confirmRestore){const v=clone(t.versions.find(v=>v.id===b.dataset.confirmRestore));snapshot(t,true);Object.assign(t,v.requirements);t.activities=v.activities;t.quote=v.quote;closeModal();day=1;mutate(t,'Đã khôi phục phiên bản.');return}
if(b.dataset.doc){const d=state.docs.find(d=>d.id===b.dataset.doc);openModal(d.title,'<div class="doc-body">'+esc(d.body)+'</div>');return}
if(b.dataset.editRate)return rateForm(b.dataset.editRate);
if(b.dataset.addOffer)return offerForm(b.dataset.addOffer);
if(b.dataset.editOffer)return offerForm(b.dataset.rateId,b.dataset.editOffer);
const a=b.dataset.action;if(!a)return;
if(a==='new-trip')tripForm(false);
else if(a==='edit-trip')tripForm(true);
else if(a==='add-activity')activityForm();
else if(a==='cancel')closeModal();
else if(a==='generate')generate();
else if(a==='snapshot')snapshot();
else if(a==='export')exportTrip();
else if(a==='recheck'){render();toast('Đã kiểm tra thời gian và ngân sách.')}
else if(a==='approve'){if(checks(t).some(x=>x.level==='error'))return toast('Xử lý các lỗi trước khi đánh dấu đã rà soát.');t.status='REVIEWED';save();render();toast('Đã rà soát nội bộ. Dữ liệu dịch vụ vẫn cần xác minh.')}
else if(a==='new-doc')docForm();
else if(a==='new-rate')rateForm();
else if(a==='export-data')download('tripwise-data.json',JSON.stringify(state,null,2),'application/json');
}
app.addEventListener('click',click);$('#modal-body').addEventListener('click',click);
app.addEventListener('change',e=>{if(e.target.id==='status-filter'){const p=route().p;p.delete('page');e.target.value?p.set('status',e.target.value):p.delete('status');location.hash='trips'+(p.size?'?'+p:'');return}if(e.target.dataset.quote){const r=trip().quote.find(r=>r.id===e.target.dataset.quote),f=e.target.dataset.field,raw=e.target.value,n=f==='price'?Number(String(raw).replace(/\a/g,'')):Number(raw);if(!Number.isFinite(n)||n<0||(f==='qty'&&(!Number.isInteger(n)||n>9999))||(f==='price'&&n>1e9)){toast('Nhập số không âm trong giới hạn.');render();return}r[f]=n;mutate(trip(),'Đã tính lại báo giá.')}});
app.addEventListener('input',e=>{const map={'trip-search':'trips','doc-search':'knowledge','rate-search':'rates'};if(map[e.target.id]){const value=e.target.value,id=e.target.id,caret=e.target.selectionStart;app.querySelector('[data-clear="'+id+'"]').hidden=!value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const p=route().p;if(id==='trip-search'||id==='rate-search')p.delete('page');value?p.set('q',value):p.delete('q');history.replaceState(null,'','#'+map[id]+(p.size?'?'+p:''));render();const el=$('#'+id);if(el){el.focus();el.setSelectionRange(caret,caret)}},180)}});
window.addEventListener('hashchange',()=>{clearTimeout(searchTimer);render()});render();save();
